{     e <- "TF24_Env"     k_mem <- 0.05     period <- 0.12     t_end <- 0.6     s <- TF24t_Strategy()     s$k_mean_leaf_temp <- k_mem     p <- Individual("TF24t", e)(s)     env <- Environment("TF24t")     t_drive <- seq(0, t_end * 1.15, length.out = 230)     env$extrinsic_drivers_set_variable("air_temp", t_drive, 27 +          6 * sin(2 * pi * t_drive/period))     runner <- OdeRunner("TF24t")(IndividualRunner("TF24t", e)(p,          env))     rec <- list()     while (runner$time < t_end) {         runner$step()         ind <- runner$object$individual         rec[[length(rec) + 1L]] <- data.frame(time = runner$time,              air_temp = env$extrinsic_drivers_evaluate("air_temp",                  min(runner$time, t_end)), operating = ind$aux("operating_leaf_temp"),              running = ind$state("mean_leaf_temp"))     }     do.call(rbind, rec) }
